      "content": "{\n  \"name\": \"dsh-any-background\",\n  \"version\": \"0.4.3\",\n  \"description\": \"Appearance plugin for DeepSeek Harness: custom theme color (PS-style color wheel), background wallpaper with opacity/blur controls, and separate main/settings interface opacity.\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"plugin\",\n    \"dsh-plugin\",\n    \"theme\",\n    \"wallpaper\",\n    \"web-ui\"\n  ],\n  \"homepage\": \"https://github.com/Tkingxiao/dsh-any-background#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Tkingxiao/dsh-any-background/issues\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Tkingxiao/dsh-any-background.git\"\n  },\n  \"license\": \"MIT\",\n  \"author\": \"Tkingxiao\",\n  \"type\": \"module\",\n  \"engines\": {\n    \"dsh\": \"0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.1 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-alpha.4 || 0.2.1-alpha.5 || 0.2.1-rc.1 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-alpha.2 || >=0.2.0-rc.1\"\n  },\n  \"exports\": {\n    \".\": {\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"default\": \"./lib/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"main\": \"lib/index.js\",\n  \"directories\": {\n    \"lib\": \"lib\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"lib/client.js.map\",\n    \"cordis.patch.yml\"\n  ],\n  \"scripts\": {\n    \"bundle\": \"tsdown\",\n    \"test\": \"npm run bundle && node scripts/smoke.mjs\",\n    \"watch\": \"tsdown --watch\",\n    \"typecheck\": \"tsc -p tsconfig.json\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh-home-paths\": \"^0.1.0-rc.6\",\n    \"@types/node\": \"^26.2.0\",\n    \"@types/react\": \"^19.2.18\",\n    \"@types/react-dom\": \"^19.2.4\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^7.0.2\",\n    \"unrun\": \"^0.3.1\"\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/dsh-home-paths\": \"^0.1.0-rc.6\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.1 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-alpha.4 || 0.2.1-alpha.5 || 0.2.1-rc.1 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-alpha.2 || >=0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.1 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-alpha.4 || 0.2.1-alpha.5 || 0.2.1-rc.1 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-alpha.2 || >=0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.1 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-alpha.4 || 0.2.1-alpha.5 || 0.2.1-rc.1 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-alpha.2 || >=0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.1 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-alpha.4 || 0.2.1-alpha.5 || 0.2.1-rc.1 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-alpha.2 || >=0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-sidebar-right\": \"0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.1 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-alpha.4 || 0.2.1-alpha.5 || 0.2.1-rc.1 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-alpha.2 || >=0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \"0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-alpha.1 || 0.2.1-alpha.2 || 0.2.1-alpha.3 || 0.2.1-alpha.4 || 0.2.1-alpha.5 || 0.2.1-rc.1 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-alpha.2 || >=0.2.0-rc.1\",\n    \"react\": \"^18.2.0\",\n    \"dsh-better-sidebar\": \">=0.4.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"dsh-better-sidebar\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-sidebar-right\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    },\n  